static const char *tool_error_code(int status)
{
    switch (status) {
    case AGENT_ERROR_INVALID:
        return "invalid";
    case AGENT_ERROR_LIMIT:
        return "limit";
    case AGENT_ERROR_TIMEOUT:
        return "timeout";
    case AGENT_ERROR_CANCELLED:
