        if (best == UINT32_MAX) {
            break;
        }

        ret = append_skill(&agent->skills[best], buffer, buffer_size, &used);
        if (ret != AGENT_OK) {
            return ret;
        }

        done[best] = true;
        done_count++;
    }

    if (written) {
        *written = used;
    }
    return AGENT_OK;
}

